import React from "react";
import { 
  DashboardIcon, 
  UsersIcon, 
  TasksIcon, 
  MetricsIcon, 
  SettingsIcon,
  CloseIcon
} from "./Icons";

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  currentView: string;
  onViewChange: (view: string) => void;
}

const menuItems = [
  {
    id: "dashboard",
    name: "Dashboard",
    icon: DashboardIcon,
  },
  {
    id: "clients",
    name: "Clients",
    icon: UsersIcon,
  },
  {
    id: "tasks",
    name: "Tasks",
    icon: TasksIcon,
  },
  {
    id: "metrics",
    name: "Metrics",
    icon: MetricsIcon,
  },
  {
    id: "settings",
    name: "Settings",
    icon: SettingsIcon,
  },
];

export const Sidebar: React.FC<SidebarProps> = ({
  isOpen,
  onClose,
  currentView,
  onViewChange,
}) => {
  return (
    <>
      {/* Desktop Sidebar */}
      <div
        className={`hidden lg:flex lg:flex-col lg:fixed lg:inset-y-0 transition-all duration-300 ${
          isOpen ? "lg:w-64" : "lg:w-16"
        }`}
      >
        <div className="flex flex-col flex-grow bg-white shadow-sm border-r border-secondary-200">
          {/* Logo section */}
          <div className="flex items-center flex-shrink-0 px-4 py-4">
            <div className="flex items-center">
              <div className="flex-shrink-0 w-8 h-8 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                <span className="text-sm font-bold text-white">TC</span>
              </div>
              {isOpen && (
                <div className="ml-3 transition-all duration-300">
                  <h2 className="text-sm font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              )}
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-2 py-4 space-y-2">
            {menuItems.map((item) => {
              const isActive = currentView === item.id;
              const IconComponent = item.icon;

              return (
                <button
                  key={item.id}
                  onClick={() => onViewChange(item.id)}
                  className={`group flex items-center w-full px-3 py-3 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 ${
                    isActive
                      ? "bg-primary-50 text-primary-700 shadow-sm border-l-4 border-primary-500"
                      : "text-secondary-600 hover:bg-secondary-50 hover:text-secondary-900 hover:shadow-sm"
                  }`}
                >
                  <div
                    className={`flex-shrink-0 transition-all duration-200 ${
                      isActive
                        ? "text-primary-500 scale-110"
                        : "text-secondary-400 group-hover:text-secondary-500 group-hover:scale-105"
                    }`}
                  >
                    <IconComponent size="lg" />
                  </div>
                  {isOpen && (
                    <span className="ml-3 transition-all duration-300 opacity-100">
                      {item.name}
                    </span>
                  )}
                  {!isOpen && (
                    <div className="absolute left-16 bg-secondary-900 text-white text-xs rounded px-2 py-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-50 whitespace-nowrap">
                      {item.name}
                    </div>
                  )}
                </button>
              );
            })}
          </nav>

          {/* Footer */}
          <div className="flex-shrink-0 p-4">
            {isOpen ? (
              <div className="bg-secondary-50 rounded-lg p-3 border border-secondary-100 shadow-sm">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="w-8 h-8 bg-success-100 rounded-full flex items-center justify-center shadow-sm">
                      <div className="w-3 h-3 bg-success-500 rounded-full animate-pulse"></div>
                    </div>
                  </div>
                  <div className="ml-3">
                    <p className="text-xs font-medium text-secondary-900">
                      System Status
                    </p>
                    <p className="text-xs text-secondary-500">
                      All systems operational
                    </p>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex justify-center">
                <div className="w-8 h-8 bg-success-100 rounded-full flex items-center justify-center shadow-sm">
                  <div className="w-3 h-3 bg-success-500 rounded-full animate-pulse"></div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Sidebar */}
      <div
        className={`lg:hidden fixed inset-0 z-50 transition-transform duration-300 ${
          isOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex">
          {/* Sidebar content */}
          <div className="flex flex-col w-64 bg-white shadow-xl">
            {/* Logo section */}
            <div className="flex items-center justify-between flex-shrink-0 px-4 py-4 border-b border-secondary-200">
              <div className="flex items-center">
                <div className="flex-shrink-0 w-8 h-8 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                  <span className="text-sm font-bold text-white">TC</span>
                </div>
                <div className="ml-3">
                  <h2 className="text-sm font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              </div>
              <button
                onClick={onClose}
                className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full transition-colors duration-200"
              >
                <CloseIcon size="lg" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-4 py-4 space-y-2 overflow-y-auto">
              {menuItems.map((item) => {
                const isActive = currentView === item.id;
                const IconComponent = item.icon;

                return (
                  <button
                    key={item.id}
                    onClick={() => {
                      onViewChange(item.id);
                      onClose();
                    }}
                    className={`group flex items-center w-full px-3 py-3 text-sm font-medium rounded-lg transition-all duration-200 ${
                      isActive
                        ? "bg-primary-50 text-primary-700 shadow-sm border-l-4 border-primary-500"
                        : "text-secondary-600 hover:bg-secondary-50 hover:text-secondary-900 hover:shadow-sm"
                    }`}
                  >
                    <div
                      className={`flex-shrink-0 transition-all duration-200 ${
                        isActive
                          ? "text-primary-500"
                          : "text-secondary-400 group-hover:text-secondary-500"
                      }`}
                    >
                      <IconComponent size="lg" />
                    </div>
                    <span className="ml-3">{item.name}</span>
                  </button>
                );
              })}
            </nav>

            {/* Footer */}
            <div className="flex-shrink-0 p-4 border-t border-secondary-200">
              <div className="bg-secondary-50 rounded-lg p-3 border border-secondary-100 shadow-sm">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="w-8 h-8 bg-success-100 rounded-full flex items-center justify-center shadow-sm">
                      <div className="w-3 h-3 bg-success-500 rounded-full animate-pulse"></div>
                    </div>
                  </div>
                  <div className="ml-3">
                    <p className="text-xs font-medium text-secondary-900">
                      System Status
                    </p>
                    <p className="text-xs text-secondary-500">
                      All systems operational
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Overlay */}
          <div className="flex-1 bg-black bg-opacity-50" onClick={onClose} />
        </div>
      </div>
    </>
  );
};
